#include "poly.hpp"
#include <filesystem>
#include <time.h>
using Relation=std::array<int,12>;
U cpu_time(){timespec t{};clock_gettime(CLOCK_PROCESS_CPUTIME_ID,&t);return U(t.tv_sec)*1000000000ULL+U(t.tv_nsec);}
std::vector<Relation> relations(const EC&ec,const std::vector<Point>&base,Point R,const std::vector<std::pair<int,int>>&roots){std::vector<Relation>out;for(auto[i,j]:roots)for(int s:{1,-1})for(int t:{1,-1}){Point a=s==1?base[i]:ec.neg(base[i]),b=t==1?base[j]:ec.neg(base[j]);if(ec.op(a,b)==R){Relation row{};row[i]+=s;row[j]+=t;if(std::find(out.begin(),out.end(),row)==out.end())out.push_back(row);}}return out;}
struct RowSpace{std::vector<std::array<U,13>>rows;std::vector<int>pivots;bool add_row(const Relation&coeff,U rhs){std::array<U,13>v{};for(int i=0;i<12;i++)v[i]=coeff[i]>=0?U(coeff[i]):ORDER-U(-coeff[i]);v[12]=rhs;for(size_t r=0;r<rows.size();r++){U c=v[pivots[r]];if(c)for(int k=0;k<13;k++)v[k]=sub(v[k],mul(c,rows[r][k],ORDER),ORDER);}int pivot=0;while(pivot<12&&!v[pivot])pivot++;if(pivot==12){need(v[12]==0,"inconsistent relation row");return false;}U z=power(v[pivot],ORDER-2,ORDER);for(U&x:v)x=mul(x,z,ORDER);for(auto&r:rows){U c=r[pivot];if(c)for(int k=0;k<13;k++)r[k]=sub(r[k],mul(c,v[k],ORDER),ORDER);}size_t at=0;while(at<pivots.size()&&pivots[at]<pivot)at++;rows.insert(rows.begin()+std::ptrdiff_t(at),v);pivots.insert(pivots.begin()+std::ptrdiff_t(at),pivot);return true;}U recover(const Relation&c)const{need(rows.size()==12,"rank insufficient");U k=0;for(int i=0;i<12;i++){U coefficient=c[i]>=0?U(c[i]):ORDER-U(-c[i]);k=add(k,mul(coefficient,rows[i][12],ORDER),ORDER);}return k;}};
struct Probe{json record;std::vector<Relation>rels;};
Probe probe(const EC&ec,const std::vector<Point>&base,Point R,bool trace){need(!R.infinity,"identity probe unsupported");U whole=ns();Algebra::Count construction;Algebra::counts=&construction;auto f=Algebra::f3(R.x,ec.a,ec.b),gx=Algebra::factor_poly(base,false),gy=Algebra::factor_poly(base,true);Algebra::counts=nullptr;U constructNs=ns()-whole;Algebra::Count count;Algebra::counts=&count;U t=ns(),cpu=cpu_time();auto result=Algebra::groebner({f,gx,gy},trace);U cpuNs=cpu_time()-cpu,gbNs=ns()-t;Algebra::counts=nullptr;
 t=ns();std::vector<std::pair<int,int>>roots;if(!result.unit)for(int i=0;i<12;i++)for(int j=0;j<12;j++){bool ok=true;for(const auto&p:result.basis)if(Algebra::evaluate(p,base[i].x,base[j].x)!=0){ok=false;break;}if(ok)roots.emplace_back(i,j);}auto rel=relations(ec,base,R,roots);U rootNs=ns()-t;
 t=ns();std::vector<std::pair<int,int>>expected;for(int i=0;i<12;i++)for(int j=0;j<12;j++)if(Algebra::evaluate(f,base[i].x,base[j].x)==0)expected.emplace_back(i,j);need(roots==expected,"GB finite-grid variety mismatch");if(!result.unit){for(const auto&p:std::vector<Algebra::Poly>{f,gx,gy})need(Algebra::reduce(p,result.basis).empty(),"input membership");for(size_t i=0;i<result.basis.size();i++)for(size_t j=0;j<i;j++)need(Algebra::reduce(Algebra::spol(result.basis[i],result.basis[j]),result.basis).empty(),"Buchberger criterion");}
 json rec={{"R",wire(R)},{"construction_ns",constructNs},{"construction_counters",construction.wire()},{"gb_wall_ns",gbNs},{"gb_process_cpu_ns",cpuNs},{"gb_counters",count.wire()},{"root_and_relation_ns",rootNs},{"independent_checks_ns",ns()-t},{"dreg_top_forms_first_zero_hilbert_degree",Algebra::dreg_top_forms(12)},{"dreg_definition","First zero Hilbert-function degree of (X^12,Y^12,X^2Y^2), not CM regularity of the homogenized ideal"},{"gb_basis",Algebra::wire(result.basis)},{"unit_ideal",result.unit},{"roots",roots},{"relations",rel},{"independent_grid_and_point_checks",true},{"buchberger_criterion_checked",!result.unit},{"pair_events",result.events},{"whole_probe_wall_ns",ns()-whole}};return{rec,rel};}
void prepare_ic(const std::string&root){need(!std::filesystem::exists(root+"/data/ic_factorbases.json"),"refuse factorbase overwrite");auto family=load(root+"/data/family.json");Random rng(root+"/data/ic_randomness.jsonl");EC ec{val(family["nodes"][0]["a"]),val(family["nodes"][0]["b"])};json bases=json::object(),tapes=json::array();json first=json::array();for(int g=0;g<10;g++){std::vector<Point>base;std::set<U>xs;while(base.size()<12){auto P=sample(ec,rng,"ic_factorbase/"+std::to_string(g));if(xs.insert(P.x).second)base.push_back(P);}json b=json::array();for(Point P:base)b.push_back(wire(P));first.push_back(b);json tape=json::array();for(int i=0;i<20;i++)tape.push_back(std::to_string(rng.below(ORDER-1,"ic_setup_scalar/"+std::to_string(g))+1));tapes.push_back(tape);}bases["0"]=first;
 for(int cid=1;cid<46;cid++){auto node=family["nodes"][cid];int parent=node["parent"],edge=node["discovery_edge"];auto b=bases[std::to_string(parent)];for(auto&list:b)for(auto&P:list)P=wire(map_point(point(P),family["edges"][edge]));bases[std::to_string(cid)]=b;}
 U checked=0;for(int cid=0;cid<46;cid++){EC e{val(family["nodes"][cid]["a"]),val(family["nodes"][cid]["b"])};for(auto&b:bases[std::to_string(cid)]){std::set<U>xs;for(auto&w:b){Point P=point(w);need(!P.infinity&&e.on(P)&&e.scalar(ORDER,P).infinity&&xs.insert(P.x).second,"factorbase validity");checked++;}}}
 save(root+"/data/ic_factorbases.json",bases);save(root+"/data/ic_setup_tapes.json",tapes);save(root+"/data/ic_preparation.json",{{"passed",true},{"points_checked",checked},{"base_size_sign_orbits",12},{"bases_per_curve",10},{"setup_probes_per_base",20},{"random_words",rng.index},{"factorbase_logs_known_or_imported",false}});}
int main(int argc,char**argv){try{need(argc>=3,"ROOT prepare|probe|all");std::string root=argv[1],mode=argv[2];if(mode=="prepare"){prepare_ic(root);return 0;}auto family=load(root+"/data/family.json"),fixtures=load(root+"/data/fixtures.json"),bases=load(root+"/data/ic_factorbases.json"),tapes=load(root+"/data/ic_setup_tapes.json");std::filesystem::create_directories(root+"/runs/ic");const auto binding=load(root+"/IC_FROZEN.json");int end=mode=="probe"?1:46;
 for(int cid=0;cid<end;cid++){std::string prefix=root+"/runs/ic/curve_"+std::to_string(cid);if(std::filesystem::exists(prefix+".complete.json")){need(load(prefix+".complete.json")["binding"]==binding,"IC checkpoint binding");continue;}if(std::filesystem::exists(prefix+".jsonl"))std::filesystem::rename(prefix+".jsonl",prefix+".interrupted_"+std::to_string(ns())+".jsonl");std::ofstream log(prefix+".jsonl");need(bool(log),"IC log open");EC ec{val(family["nodes"][cid]["a"]),val(family["nodes"][cid]["b"])};U setupTrials=0,setupRelations=0,targetRelations=0,solved=0,controls=0;json ranks=json::array();
 for(int g=0;g<10;g++){std::vector<Point>base;for(auto&p:bases[std::to_string(cid)][g])base.push_back(point(p));Point P=point(fixtures[std::to_string(cid)][g*10]["P"]);RowSpace matrix;
 std::map<std::tuple<bool,U,U>,std::set<Relation>>oracle;U oracleStart=ns();for(int i=0;i<12;i++)for(int j=0;j<12;j++)for(int s:{1,-1})for(int t:{1,-1}){Point R=ec.op(s==1?base[i]:ec.neg(base[i]),t==1?base[j]:ec.neg(base[j]));Relation rel{};rel[i]+=s;rel[j]+=t;oracle[{R.infinity,R.x,R.y}].insert(rel);}U oracleNs=ns()-oracleStart;auto checkedProbe=[&](Point R){auto p=probe(ec,base,R,true);std::set<Relation>actual(p.rels.begin(),p.rels.end());need(actual==oracle[{R.infinity,R.x,R.y}],"independent signed-point oracle mismatch");p.record["independent_signed_point_oracle_checked"]=true;p.record["oracle_verifier_setup_ns"]=oracleNs;p.record["oracle_not_used_by_solver"]=true;return p;};
 for(int i=0;i<2;i++){Point R=i==0?ec.op(base[0],base[1]):ec.scalar(2,base[0]);auto p=checkedProbe(R);need(!p.rels.empty(),"positive control failed");p.record["stage"]="positive_control";p.record["generator"]=g;p.record["index"]=i;log<<p.record.dump()<<'\n';log.flush();controls++;}
 for(int i=0;i<20;i++){U t=val(tapes[g][i]);Point R=ec.scalar(t,P);auto p=checkedProbe(R);bool increased=false;for(auto&rel:p.rels)increased=matrix.add_row(rel,t)||increased;p.record["stage"]="setup";p.record["generator"]=g;p.record["index"]=i;p.record["known_setup_scalar"]=std::to_string(t);p.record["rank"]=matrix.rows.size();p.record["rank_increased"]=increased;log<<p.record.dump()<<'\n';log.flush();setupTrials++;if(!p.rels.empty())setupRelations++;}
 ranks.push_back(matrix.rows.size());for(int key=0;key<10;key++){int id=g*10+key;auto row=fixtures[std::to_string(cid)][id];Point Q=point(row["Q"]);auto p=checkedProbe(Q);bool recovered=false;json answer=nullptr;if(!p.rels.empty())targetRelations++;if(matrix.rows.size()==12&&!p.rels.empty()){U k=matrix.recover(p.rels[0]);recovered=ec.scalar(k,P)==Q;if(recovered){answer=std::to_string(k);solved++;}}p.record["stage"]="target";p.record["generator"]=g;p.record["key_index"]=key;p.record["instance"]=id;p.record["setup_rank"]=matrix.rows.size();p.record["recovered_k"]=answer;p.record["verified_recovery"]=recovered;p.record["recovery_status"]=recovered?"solved":matrix.rows.size()<12?"insufficient_setup_rank":"target_relation_not_found";log<<p.record.dump()<<'\n';log.flush();}}
 log.close();save(prefix+".complete.json",{{"binding",binding},{"curve",cid},{"setup_trials",setupTrials},{"setup_probes_with_relations",setupRelations},{"target_probes",100},{"target_probes_with_relations",targetRelations},{"positive_controls_passed",controls},{"factorbase_ranks",ranks},{"full_log_recoveries",solved},{"all_diagnostics_checked",true},{"full_ic_recovery_requirement_complete",solved==100},{"timing_class","CPU-only L0 diagnostic, concurrent work"}});std::cout<<"IC curve "<<cid<<" controls="<<controls<<" setup_relations="<<setupRelations<<" targets_with_relations="<<targetRelations<<" full_recoveries="<<solved<<std::endl;}
 return 0;}catch(const std::exception&e){Algebra::counts=nullptr;std::cerr<<"ERROR "<<e.what()<<'\n';return 1;}}
